#include "engine/procgen/IJobService.hpp"
#include <algorithm>
#include <chrono>
#include <map>
#include <mutex>
#include <utility>
namespace engine::jobs{namespace{class Service final:public IJobService{struct Rec{JobSnapshot s;std::uint64_t timeout{0};std::chrono::steady_clock::time_point started;};mutable std::mutex mutex_;std::map<std::uint64_t,Rec>jobs_;std::uint64_t next_{1};static bool terminal(JobState s){return s==JobState::Completed||s==JobState::Failed||s==JobState::Cancelled||s==JobState::TimedOut;}public:std::uint64_t start(const std::string&stage,std::uint64_t timeout,std::string&e)override{if(stage.empty()){e="empty_job";return 0;}std::lock_guard lock(mutex_);Rec r;r.s.id=next_++;const auto id=r.s.id;r.s.state=JobState::Running;r.s.stage=stage;r.timeout=timeout;r.started=std::chrono::steady_clock::now();jobs_.emplace(id,std::move(r));return id;}bool update(std::uint64_t id,double p,const std::string&stage,std::string&e)override{if(p<0||p>1){e="invalid_progress";return false;}std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}if(terminal(i->second.s.state)){e="job_terminal";return false;}if(p<i->second.s.progress){e="progress_regressed";return false;}i->second.s.progress=p;if(!stage.empty())i->second.s.stage=stage;return true;}bool complete(std::uint64_t id,const std::vector<JobArtifact>&a,std::string&e)override{std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}if(terminal(i->second.s.state)){e="job_terminal";return false;}i->second.s.progress=1;i->second.s.state=JobState::Completed;i->second.s.stage="completed";i->second.s.artifacts=a;return true;}bool fail(std::uint64_t id,const std::string&msg,std::string&e)override{std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}if(terminal(i->second.s.state)){e="job_terminal";return false;}i->second.s.state=JobState::Failed;i->second.s.error=msg;i->second.s.stage="failed";return true;}bool poll(std::uint64_t id,JobSnapshot&o,std::string&e)const override{std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}o=i->second.s;return true;}bool cancel(std::uint64_t id,std::string&e)override{std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}if(terminal(i->second.s.state)){e="job_terminal";return false;}i->second.s.state=JobState::Cancelled;i->second.s.stage="cancelled";return true;}bool wait(std::uint64_t id,std::uint64_t ms,JobSnapshot&o,std::string&e)override{std::lock_guard lock(mutex_);auto i=jobs_.find(id);if(i==jobs_.end()){e="job_not_found";return false;}auto&j=i->second;if(!terminal(j.s.state)){auto elapsed=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-j.started).count());if(j.timeout&&elapsed>=j.timeout){j.s.state=JobState::TimedOut;j.s.error="timeout";}else if(ms>0&&elapsed>=ms){j.s.state=JobState::TimedOut;j.s.error="wait_deadline";}}o=j.s;return true;}std::vector<JobSnapshot>list()const override{std::lock_guard lock(mutex_);std::vector<JobSnapshot>o;for(const auto&[_,r]:jobs_)o.push_back(r.s);std::reverse(o.begin(),o.end());return o;}};}std::unique_ptr<IJobService>create_job_service(){return std::make_unique<Service>();}}
